CREATE TABLE shared_expense_groups (id BIGSERIAL PRIMARY KEY, account_id BIGINT NOT NULL REFERENCES accounts(id), name VARCHAR(150) NOT NULL, created_by BIGINT NOT NULL REFERENCES users(id), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_shared_groups_account ON shared_expense_groups(account_id);
CREATE TABLE shared_group_members (id BIGSERIAL PRIMARY KEY, group_id BIGINT NOT NULL REFERENCES shared_expense_groups(id), user_id BIGINT REFERENCES users(id), member_name VARCHAR(150) NOT NULL, email VARCHAR(255), mobile VARCHAR(20), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(group_id, user_id));
CREATE INDEX idx_shared_members_group ON shared_group_members(group_id);
CREATE TABLE shared_expenses (id BIGSERIAL PRIMARY KEY, group_id BIGINT NOT NULL REFERENCES shared_expense_groups(id), created_by BIGINT NOT NULL REFERENCES users(id), description VARCHAR(500) NOT NULL, category VARCHAR(100), expense_date DATE NOT NULL, total_amount DECIMAL(19,2) NOT NULL, split_type VARCHAR(20) NOT NULL, reversed BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_shared_expenses_group_date ON shared_expenses(group_id, expense_date);
CREATE TABLE shared_expense_payers (id BIGSERIAL PRIMARY KEY, expense_id BIGINT NOT NULL REFERENCES shared_expenses(id), member_id BIGINT NOT NULL REFERENCES shared_group_members(id), paid_amount DECIMAL(19,2) NOT NULL, UNIQUE(expense_id, member_id));
CREATE TABLE shared_expense_shares (id BIGSERIAL PRIMARY KEY, expense_id BIGINT NOT NULL REFERENCES shared_expenses(id), member_id BIGINT NOT NULL REFERENCES shared_group_members(id), owed_amount DECIMAL(19,2) NOT NULL, UNIQUE(expense_id, member_id));
CREATE TABLE shared_settlements (id BIGSERIAL PRIMARY KEY, group_id BIGINT NOT NULL REFERENCES shared_expense_groups(id), paid_by_member_id BIGINT NOT NULL REFERENCES shared_group_members(id), paid_to_member_id BIGINT NOT NULL REFERENCES shared_group_members(id), amount DECIMAL(19,2) NOT NULL, settlement_date DATE NOT NULL, payment_mode VARCHAR(30), notes VARCHAR(500), reversed BOOLEAN NOT NULL DEFAULT FALSE, created_by BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(paid_by_member_id <> paid_to_member_id));
CREATE INDEX idx_shared_settlements_group ON shared_settlements(group_id);
